query SIM_getUpcomingRace($localSim: LocalSim, $oddsTypes: [OddsType]) {
  commonMeetings(localSim: $localSim) {
    id
    venueCode
    date
    status
    season
    totalNumberOfRace
    currentNumberOfRace
    country {
      code
      namech
      nameen
      seq
    }
    races {
      id
      no
      postTime
      status
      raceResults {
        status
      }
      raceName_en
      raceName_ch
      raceTrack {
        code
        description_ch
        description_en
      }
      countryCodeNm {
        code
        english
        chinese
      }
    }
    pmPools(oddsTypes: $oddsTypes) {
      oddsType
      status
      leg {
        races
      }
    }
  }
}
